package app.noir.mobile;
import android.app.job.JobInfo;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;
import org.junit.Test;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;

public final class PhoneReadyTest {
 JSONObject json(String text)throws Exception{return new JSONObject(text);}
 Context isolated(){Context real=InstrumentationRegistry.getInstrumentation().getTargetContext();File root=new File(real.getFilesDir(),"ready-tests-"+UUID.randomUUID());root.mkdirs();return new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return root;}@Override public File getExternalFilesDir(String type){File external=new File(root,"external");external.mkdirs();return external;}};}
 @Test public void budgetCountsActualPartialFilesAndReservations()throws Exception{long gb=PhoneReady.GB;JSONArray jobs=new JSONArray().put(json("{id:'partial',status:'paused',bytes:1,diskBytes:1073741824,total:2147483648}")).put(json("{id:'done',status:'complete',bytes:2147483648,diskBytes:2147483648,total:2147483648}"));assertEquals(3*gb,PhoneReady.occupied(jobs));assertEquals(gb,PhoneReady.reserved(jobs,"new"));assertEquals(0,PhoneReady.reserved(jobs,"partial"));assertEquals("",PhoneReady.storageReason(3*gb,gb,gb,5*gb,5*gb));assertTrue(PhoneReady.storageReason(3*gb,gb,gb+1,5*gb,10*gb).contains("budget"));assertTrue(PhoneReady.storageReason(0,0,gb,5*gb,3*gb-1).contains("2 GB"));assertTrue(PhoneReady.storageReason(0,0,-1,5*gb,10*gb).contains("confirmed"));assertFalse(PhoneReady.storageReason(Long.MAX_VALUE-2,0,10,Long.MAX_VALUE,Long.MAX_VALUE).isEmpty());}
 @Test public void neverEvictsUnwatchedOrManualFilesEvenOverBudget()throws Exception{JSONObject job=json("{id:'a',readyManaged:true,status:'complete'}"),unwatched=json("{id:'a',progress:{position:120}}"),watched=json("{id:'a',progress:{completed:true}} ");assertFalse(PhoneReady.cleanupEligible(job,unwatched,true,false,false));assertTrue(PhoneReady.cleanupEligible(job,watched,true,false,false));assertFalse(PhoneReady.cleanupEligible(job,watched,false,false,false));assertFalse(PhoneReady.cleanupEligible(job,watched,true,true,false));assertFalse(PhoneReady.cleanupEligible(job,watched,true,false,true));DataStore.put(job,"pinned",true);assertFalse(PhoneReady.cleanupEligible(job,watched,true,false,false));DataStore.put(job,"pinned",false);DataStore.put(job,"readyManaged",false);assertFalse(PhoneReady.cleanupEligible(job,watched,true,false,false));DataStore.put(job,"readyManaged",true);DataStore.put(job,"status","paused");assertFalse(PhoneReady.cleanupEligible(job,watched,true,false,false));assertFalse(PhoneReady.storageReason(6*PhoneReady.GB,0,0,PhoneReady.DEFAULT_BUDGET,20*PhoneReady.GB).isEmpty());assertFalse(PhoneReady.cleanupEligible(job,unwatched,true,false,false));}
 @Test public void nextTwoAiredUnwatchedAndStartedShowsFirstWithoutMutations()throws Exception{long now=System.currentTimeMillis();List<JSONObject> items=new ArrayList<>();items.add(json("{id:'a1',group:'a',season:1,episode:1,airsAt:'2020-01-01'}"));items.add(json("{id:'z1',group:'z',season:1,episode:1,airsAt:'2020-01-01',progress:{completed:true}}"));items.add(json("{id:'z3',group:'z',season:1,episode:3,airsAt:'2020-01-01'}"));items.add(json("{id:'z2',group:'z',season:1,episode:2,airsAt:'2020-01-01',progress:{position:10}}"));items.add(json("{id:'z4',group:'z',season:1,episode:4,airsAt:'2020-01-01'}"));items.add(json("{id:'future',group:'a',season:1,episode:2,airsAt:'2099-01-01'}"));items.add(json("{id:'unknown',group:'a',season:1,episode:3}"));String original=items.toString();List<JSONObject> result=PhoneReady.select(items,json("{a:2,z:2}"),now);assertEquals(3,result.size());assertEquals("z2",result.get(0).optString("id"));assertEquals("z3",result.get(1).optString("id"));assertEquals("a1",result.get(2).optString("id"));DataStore.put(result.get(0),"title","changed");assertEquals(original,items.toString());}
 @Test public void wholeSeasonDoesNotSpillAndDuplicateEpisodesCountOnce()throws Exception{List<JSONObject> items=new ArrayList<>();for(int season=1;season<=2;season++)for(int episode=1;episode<=4;episode++)items.add(json("{id:'"+season+"-"+episode+"',group:'s',season:"+season+",episode:"+episode+",airsAt:'2020-01-01'}"));items.add(DataStore.copy(items.get(0)));assertEquals(2,PhoneReady.select(items,json("{s:2}"),System.currentTimeMillis()).size());assertEquals(4,PhoneReady.select(items,json("{s:-1}"),System.currentTimeMillis()).size());}
 @Test public void stateDefaultsProfileIsolationBoundedLogAndCancelableCleanup()throws Exception{Context c=isolated();PhoneReady p=new PhoneReady(c.getFilesDir());assertFalse(p.enabled());assertFalse(p.cleanup());assertFalse(p.paused());assertEquals(5*PhoneReady.GB,p.budget());p.keep("show",2);p.setting("enabled",true);p.setting("paused",true);p.setting("cleanup",true);JSONObject exported=p.keepReadyJson();DataStore.put(exported,"show",3);assertEquals(2,p.keepReadyJson().optInt("show"));long now=System.currentTimeMillis();p.scheduleRemoval("a",now-10*86400000L,now);assertEquals(now+86400000L,p.removals().optJSONObject(0).optLong("at"));p.protect("a",false);assertEquals(0,p.removals().length());p.scheduleRemoval("a",1,now);assertEquals(0,p.removals().length());p.scheduleRemoval("b",now,now);assertEquals(now+PhoneReady.SEVEN_DAYS,p.removals().optJSONObject(0).optLong("at"));p.protect("b",true);assertTrue(p.protectedFile("b"));for(int n=0;n<225;n++)p.log("a","reason "+n);assertEquals(200,p.snapshot().optJSONArray("why").length());PhoneReady reopened=new PhoneReady(c.getFilesDir());assertTrue(reopened.enabled());assertTrue(reopened.paused());assertEquals(2,reopened.keepReadyJson().optInt("show"));assertTrue(reopened.protectedFile("a"));File other=new File(c.getFilesDir(),"another");other.mkdirs();assertFalse(new PhoneReady(other).enabled());}
 @Test public void jobRequiresUnmeteredChargingAndPeriodicSixHours(){Context c=isolated();JobInfo job=PhoneReadyJob.jobInfo(c);assertEquals(JobInfo.NETWORK_TYPE_UNMETERED,job.getNetworkType());assertTrue(job.isRequireCharging());assertTrue(job.isPeriodic());assertTrue(job.isPersisted());assertEquals(6*3600000L,job.getIntervalMillis());assertEquals(PhoneReadyJob.class.getName(),job.getService().getClassName());assertTrue(PhoneReady.overnight(0));assertTrue(PhoneReady.overnight(5));assertFalse(PhoneReady.overnight(6));assertFalse(PhoneReady.overnight(23));}
 @Test public void scheduleMergeKeepsProgressAndUsesStableEpisodeIds()throws Exception{JSONObject first=json("{id:'pc-first',pcItemId:'pc-file-for-first',group:'show:tt123',imdb:'tt123',season:1,episode:1,progress:{completed:true},available:true}");String original=first.toString();JSONObject schedules=json("{'show:tt123':[{season:1,episode:1,airsAt:'2020-01-01'},{season:1,episode:2,airsAt:'2020-01-02',title:'Second'},{season:1,episode:3,airsAt:'2099-01-01'}]}");List<JSONObject> merged=PhoneReady.mergeSchedules(List.of(first),json("{'show:tt123':2}"),schedules);assertEquals(original,first.toString());assertEquals(3,merged.size());assertTrue(PhoneReady.watched(merged.get(0)));assertEquals(PhoneSeasonPlan.episodeId("show:tt123",1,2),merged.get(1).optString("id"));assertFalse(merged.get(1).optBoolean("available"));assertFalse(merged.get(1).has("pcItemId"));List<JSONObject> plan=PhoneReady.select(merged,json("{'show:tt123':2}"),System.currentTimeMillis());assertEquals(1,plan.size());assertEquals(2,plan.get(0).optInt("episode"));}
 @Test public void replacingAReadyFileCancelsItsCleanupOwnership()throws Exception{Context c=isolated();DownloadStore store=new DownloadStore(c);JSONObject job=json("{id:'managed',readyManaged:true,readyFileBytes:4}");File file=store.file("managed",false);Files.write(file.toPath(),new byte[4]);DataStore.put(job,"readyFileModified",file.lastModified());assertTrue(store.ownsReadyFile(job));Files.write(file.toPath(),new byte[5]);assertFalse(store.ownsReadyFile(job));}
 @Test public void automaticSearchNeverSubmitsUncachedOrPackJobs()throws Exception{List<String> requests=new ArrayList<>();PhoneDownloadProvider provider=new PhoneDownloadProvider(json("{manifest:'https://aio.invalid/config/manifest.json',torBoxKey:'fixture',realDebridKey:'fixture'}"),(url,key,form,multipart)->{requests.add(url);assertTrue(url.contains("/stream/series/"));assertNull(form);return json("{streams:[{name:'[TB+] 1080p',url:'https://cdn.invalid/ready',behaviorHints:{videoSize:1000}}, {name:'1080p',url:'https://cdn.invalid/unknown',behaviorHints:{videoSize:1000}}, {name:'[TB+] pack',infoHash:'1234567890123456789012345678901234567890'}, {name:'[TB+] unknown size',url:'https://cdn.invalid/nosize'}]}");});List<JSONObject> safe=PhoneReadyJob.readySources(provider,json("{imdb:'tt123',season:1,episode:2}"));assertEquals(1,safe.size());assertEquals("https://cdn.invalid/ready",safe.get(0).optString("url"));assertEquals(1,requests.size());}
 @Test public void manualDownloadsAreNeverAdoptedAndReadyQueueIsSeparate()throws Exception{Context c=isolated();DataStore previous=NoirApp.data;DataStore data=new DataStore(c);NoirApp.data=data;try{DownloadStore store=new DownloadStore(data.context);JSONObject manual=json("{id:'manual',title:'Manual',season:1,episode:1}"),ready=json("{id:'ready',title:'Ready',season:1,episode:2}");data.rememberPhoneItem(manual);data.rememberPhoneItem(ready);store.enqueue(manual);assertFalse(store.enqueueReady(manual,null,1000));assertFalse(store.job("manual").optBoolean("readyManaged"));assertTrue(store.enqueueReady(ready,null,1000));assertTrue(store.job("ready").optBoolean("readyManaged"));assertEquals("manual",store.next());Files.write(store.file("ready",true).toPath(),new byte[123]);assertEquals(123,store.diskJobs().optJSONObject(1).optLong("diskBytes"));store.pinReady("ready");assertTrue(store.job("ready").optBoolean("pinned"));}finally{NoirApp.data=previous;data.network.shutdownNow();data.images.shutdownNow();}}
}
